using System;
using FiresCore.Logging;
using UnityEngine;

namespace VerdantsAscent.Utilities
{
    // FiresValheimGalaxies' console banners, rendered through the shared Banner engine.
    //
    //   PrintBig()  → ringed planet with a comet streaking past, over the
    //                 FIRES GALAXIES brand. Fires at the very top of Awake
    //                 as the load announcement.
    //   Print()     → compact ringed planet + starfield over a status frame
    //                 ("TIDES FLOWING"). Fires once at first world load.
    //
    // Art generated by Tools\gen_fires_banner.ps1 (spec: FiresValheimGalaxies).
    // Color zones: starfield (White/Cyan), comet tail (Magenta/DarkMagenta),
    // planet + ring (Magenta/DarkMagenta), nebula base (DarkCyan/Cyan),
    // brand (Magenta/White).
    internal static class FiresGalaxiesBanner
    {
        private static bool s_compactPrinted;

        public static void PrintBig()
        {
            try
            {
                EmitHeader("Fires Valheim Galaxies Loading...");
                Banner.Print(ToSegments(s_bigLines));
            }
            catch (Exception ex)
            {
                Debug.LogWarning($"[FiresValheimGalaxies] Big banner failed: {ex.Message}");
            }
        }

        public static void Print()
        {
            if (s_compactPrinted) return;
            s_compactPrinted = true;
            try
            {
                EmitHeader("Fires Valheim Galaxies Loaded.");
                Banner.Print(s_compactLines);
            }
            catch (Exception ex)
            {
                Debug.LogWarning($"[FiresValheimGalaxies] Compact banner failed: {ex.Message}");
            }
        }

        // Routes the one-line header through the plugin's BepInEx log source
        // (not Debug.Log) so it prints once, colored by the shared
        // FiresLogColorPatch, without a raw white stdout duplicate.
        private static void EmitHeader(string text)
        {
            if (FiresValheimGalaxies.Log != null) FiresValheimGalaxies.Log.LogInfo(text);
            else Debug.Log($"[FiresValheimGalaxies] {text}");
        }

        private static Banner.Segment[][] ToSegments((string text, ConsoleColor color)[] lines)
        {
            var result = new Banner.Segment[lines.Length][];
            for (int i = 0; i < lines.Length; i++)
                result[i] = new[] { new Banner.Segment(lines[i].text, lines[i].color) };
            return result;
        }

        // Compact banner — ringed planet over a status frame. 31-char frame
        // body (3 lead + ╔ + 26 ═ + ╗); 🌌 is a surrogate pair, but the console
        // ADVANCES ONE column for it (no VS16), however wide the font paints the glyph, so this row pads it as one cell.
        private static readonly Banner.Segment[][] s_compactLines =
        {
            new[] { new Banner.Segment("       ·    ✦      ·",        ConsoleColor.White) },
            new[] { new Banner.Segment("            ▄████▄",          ConsoleColor.Magenta) },
            new[]
            {
                new Banner.Segment("      ──═(",       ConsoleColor.DarkCyan),
                new Banner.Segment("████████",         ConsoleColor.Magenta),
                new Banner.Segment(")═──",             ConsoleColor.DarkCyan),
            },
            new[] { new Banner.Segment("            ▀████▀   ✦",      ConsoleColor.DarkMagenta) },
            new[] { new Banner.Segment("     ✦    ·      ·",          ConsoleColor.DarkGray) },
            new[] { new Banner.Segment("   ╔══════════════════════════╗", ConsoleColor.DarkGray) },
            new[]
            {
                new Banner.Segment("   ║   ",              ConsoleColor.DarkGray),
                new Banner.Segment("[",                    ConsoleColor.Gray),
                new Banner.Segment("██████████████████",   ConsoleColor.Green),
                new Banner.Segment("]",                    ConsoleColor.Gray),
                new Banner.Segment("   ║",                 ConsoleColor.DarkGray),
            },
            new[]
            {
                new Banner.Segment("   ║     ",            ConsoleColor.DarkGray),
                new Banner.Segment("🌌 TIDES FLOWING",     ConsoleColor.Cyan),
                new Banner.Segment("      ║",               ConsoleColor.DarkGray),
            },
            new[] { new Banner.Segment("   ╚══════════════════════════╝", ConsoleColor.DarkGray) },
            new[] { new Banner.Segment("    FIRES VALHEIM GALAXIES",  ConsoleColor.Cyan) },
            new Banner.Segment[0],
            new[] { new Banner.Segment("   Fires Valheim Galaxies Loaded", ConsoleColor.Magenta) },
        };

